import{_ as s,C as a,c as i,o as r,aa as l,b as p,G as t,w as E,a as A,ab as b}from"./chunks/framework.ByRpVre_.js";const m=JSON.parse('{"title":"开服之前：你究竟需要什么样的服务器？","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/guide"},{"title":"logical-questions","link":""},{"title":"开服之前：你究竟需要什么样的服务器？","link":"/guide/logical-questions/before-start-what-server-you-want"}]},"headers":[],"relativePath":"guide/logical-questions/before-start-what-server-you-want.md","filePath":"guide/logical-questions/before-start-what-server-you-want.md"}'),_={name:"guide/logical-questions/before-start-what-server-you-want.md"};function d(u,e,C,c,h,f){const o=a("Mermaid"),B=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return r(),i("div",null,[e[1]||(e[1]=l('<h1 id="开服之前-你究竟需要什么样的服务器" tabindex="-1">开服之前：你究竟需要什么样的服务器？ <a class="header-anchor" href="#开服之前-你究竟需要什么样的服务器" aria-label="Permalink to &quot;开服之前：你究竟需要什么样的服务器？&quot;">​</a></h1><p>这不是一个能够一句话回答的问题。</p><p>笔者曾经见过很多小白服主嚷嚷着自己要开服“拯救情怀”“赚点钱”，甚至只是“为了爱好”。但是开服真的有想象的那么简单吗？我看未必。</p><p>首先，我们可以不用了解一个服务器在代码层面的运作方式，但身为一个服主，你至少需要知道这些文件的名称与作用。对服务器安装的插件和相关功能有着基础的了解，才可以至少在使用其他人的开服端时不至于问出来那么多奇葩的问题。不过实际上，我非常不推荐新手服主这么干。无论你的目的是学习还是为了乐趣，从零开始搭建服务器都可以让你积累宝贵的开服经验。而对于那些只是想圈钱的服主来说，即使你已经使用了现有的开服包，你也可以通过了解基础知识减少自己买到废品整合包的概率。</p><h2 id="_01-确定类型" tabindex="-1">01 确定类型 <a class="header-anchor" href="#_01-确定类型" aria-label="Permalink to &quot;01 确定类型&quot;">​</a></h2><p>很多新手服主往往有着不切实际的设想。看着那些高大上的服务器，嚷嚷着自己也要做一个，结果到头来只是做了一个画虎类犬的缝合怪——还白白遭到了技术大佬的嘲笑。</p><p>笔者建议，除非你有非常明确的设计路线，否则<strong>绝对不要肆意组合你所见到的主流玩法</strong>，这样不仅对玩家是一种伤害，对你正常维护服务器也会造成不小的困难。</p>',7)),(r(),p(b,null,{default:E(()=>[t(o,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20TD%0A%20%20label1%5B%22%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20label2%5B%22%E7%8E%A9%E6%B3%95%E6%98%AF%E5%90%A6%E5%9F%BA%E4%BA%8E%E7%94%9F%E5%AD%98%EF%BC%9F%22%5D%0A%20%20label2%20--%3E%20%7C%22%E6%98%AF%22%7Clabel3%5B%22%E7%8E%A9%E6%B3%95%E6%98%AF%E5%90%A6...%22%5D%0A%20%20label3%20--%3E%20%7C%22%60%E4%BB%A5%E5%BB%BA%E7%AD%91%E4%B8%BA%E4%B8%BB%60%22%7Clabelf1%5B%22%60%E5%88%9B%E9%80%A0%0A%20%20%EF%BC%88%E6%89%8B%E8%89%BA%EF%BC%89%60%22%5D%0A%20%20label3%20--%3E%20%7C%22%60%E4%BB%A5%E6%8E%A2%E7%A9%B6%E7%94%9F%E5%AD%98%E6%9C%BA%E5%88%B6%EF%BC%88%E7%BA%A2%E7%9F%B3%E7%94%B5%E8%B7%AF%EF%BC%89%E4%B8%BA%E4%B8%BB%60%22%7Clabelf2%5B%22%E7%94%9F%E7%94%B5%22%5D%0A%20%20label3%20--%3E%20%7C%22%E4%BB%A5%E7%A4%BE%E4%BA%A4%E4%B8%BA%E4%B8%BB%EF%BC%8C%E7%94%9F%E5%AD%98%E4%B8%BA%E8%BE%85%22%7Clabelf3%5B%22%60%E7%94%9F%E5%AD%98%0A%20%20%EF%BC%88%E7%A4%BE%E4%BA%A4%E7%94%9F%E5%AD%98%EF%BC%89%60%22%5D%0A%20%20label2%20--%3E%20%7C%22%E5%90%A6%22%7Clabel4%5B%22%E7%8E%A9%E6%B3%95%E6%98%AF%E5%90%A6%E4%BC%B4%E9%9A%8F%E6%98%8E%E6%98%BE%E5%89%A7%E6%83%85%EF%BC%9F%22%5D%0A%20%20label4%20--%3E%20%7C%22%E6%98%AF%22%7Clabelf4%5B%22RPG%22%5D%0A%20%20label4%20--%3E%20%7C%22%E5%90%A6%22%7Clabelf5%5B%22%E5%B0%8F%E6%B8%B8%E6%88%8F%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[A(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>以上只是一个简单的界定，旨在为了让新手简单快速确定自己想开的服务器类型。实际细分还有很多，需要按照设想进一步细化。</p><h2 id="_02-准备人员" tabindex="-1">02 准备人员 <a class="header-anchor" href="#_02-准备人员" aria-label="Permalink to &quot;02 准备人员&quot;">​</a></h2><p>不论你喜欢“白手起家”“单打独斗”还是招兵买马，拥有一个团队（或者至少一位技术）都是非常值得考虑的选择。</p><p>前面也说过，你是这个服务器的拥有者（Owner），想要真正开好一个服务器，除开自身的经验学习和外部的引导以外，你也需要一些人手帮助你维护服务器稳定，运营玩家群体，进一步分摊你的压力。</p><p>开服从来就不是一件简单的事情。把它过分看轻只会让你的压力倍增，最终因自负而被拖垮。</p><hr><p>首先，你至少需要找到一位（或者一群）愿意为你提供技术支持的热心用户。</p><p>有句话说得好，朋友多了路好走，在开服界也是如此。良好的询问态度和详细的问题内容可以帮助你超越绝大多数的服主，成为技术大佬眼里的群宠。</p><p>其次，不懂就问。你是新手，新手当然问题多。当然，大佬也有自己的事情要忙，如果询问问题长时间没有等到结果，除非万不得已，否则还是可以通过搜索引擎寻得问题的答案。重复在群里询问一个问题，甚至转发相同内容到类似群聊的询问方式都是极其不礼貌的，这会让人觉得你只是在拿热心群友当作解答问题的机器人，并不是真的有求于人。</p><p>最后，对于问问题的态度，即使是大佬出错或者出言不逊，在合理的范围内你也要适当忍受。理由上文也已经讲过，不是所有人都围着你转，也不是所有人都可以一次性理解你说的所有话，基于这个结论，如果被其他提供帮助的用户认为问题描述不清，你不能假设自己是完全无罪的。</p><p>所以，如果你不可避免地因此而与其他人甚至提供帮助者发生摩擦，适时承认错误并回到问题上是非常重要的。<strong>切忌在逻辑与道德方面与其他用户争论，这对解决一开始的问题没有任何好处</strong>。</p><h2 id="_03-测试环境" tabindex="-1">03 测试环境 <a class="header-anchor" href="#_03-测试环境" aria-label="Permalink to &quot;03 测试环境&quot;">​</a></h2><p>服务器 VPS/面板服同样是新手难趟的深水区。</p><p>在购买服务器之前，你需要好好想想。所做的服务端究竟能不能开箱即用，马上投入到生产环境当中？如果贸然购买服务器再开始填入内容逐步制作的话，玩家也会跟着你付出无形的时间成本，这对于依赖于用户粘性的国内服务器而言无疑是致命的。</p><p>服务器本身价格高昂，且租期相对较短，在计划中的服务器尚无稳定获得回报的能力前先购买 VPS 或面板服的话，可能会增加投入的沉没成本。</p><p>因此，笔者建议，先通过 <a href="https://www.natfrp.com/?page=panel&amp;module=download" target="_blank" rel="noreferrer">SakuraFRP</a> 或者 <a href="https://www.mczwlt.net/resource/mp6zv2jo" target="_blank" rel="noreferrer">PRF</a> 等方式搭建本地服务器，然后拉拢技术人员，或者独自打造服务器内容。过程可以适当参考一些其他服务器的内容，切忌照搬。对于一个服务器来说，保有一定的原创度也是留住玩家的重要因素之一。</p><p>直到服务器初步打磨完毕，可以投入生产环境的时候，就可以着手斟酌托管机的类型了。</p><ul><li>VPS 价格相对高昂，通过电脑的远程桌面登入操作，使用体验上与电脑类似。</li><li>面板服价格相对低廉，通过登录网站面板操作，使用体验上与部分开服软件类似。</li></ul><p>对于面板服，部分商家可能预先准备了便于你使用的工具，但笔者不建议过分依赖它们。<br> 原因也非常明显：这些工具样式千奇百怪五花八门，对此付出额外的学习成本显然不值得。</p><p>除此之外，笔者不推荐新手服主使用面板服，商家为了降低成本，会在一台实体机上运行多个面板服实例分别售卖给不同的用户，在这种情况下，用户的使用体验会因内存空间的挤占而大打折扣，这就是所谓的“超开”问题。<br> 另外，面板服让商家有更多为硬/软件偷工减料的机会，用户更难接触到关于实体机本身的信息，出现潜在隐患的概率进一步增加。<br> 最后，面板服本身有可能不与你习惯使用的操作系统相同，这会加大问题排查时的调试难度——因为系统本身有时候也是影响服务器运行的因素。</p>',20)),t(B),t(n)])}const g=s(_,[["render",d]]);export{m as __pageData,g as default};
